'use client';

import { BaseCodeBlockPlugin } from 'platejs';
import type { ComboboxState } from 'platejs/combobox';
import { definePlugin } from 'platejs/react';
import * as React from 'react';

import { searchEmojis, useEmojis } from '@/registry/lib/emoji-data';

import {
  InlineCombobox,
  InlineComboboxContent,
  InlineComboboxEmpty,
  InlineComboboxGroup,
  InlineComboboxItem,
  useInlineComboboxQuery,
} from './inline-combobox';

export function EmojiCombobox({
  editableRef,
}: {
  editableRef: React.RefObject<HTMLDivElement | null>;
}) {
  return (
    <InlineCombobox
      editableRef={editableRef}
      filter={false}
      plugin={EmojiPlugin}
      hideWhenNoValue
    >
      <EmojiComboboxContent />
    </InlineCombobox>
  );
}

function EmojiComboboxContent() {
  const query = useInlineComboboxQuery();
  const catalog = useEmojis(query || null);
  const emojis = React.useMemo(
    () => (Array.isArray(catalog) ? searchEmojis(catalog, query) : []),
    [catalog, query]
  );

  return (
    <InlineComboboxContent>
      {catalog === 'loading' ? (
        // An option, so Enter lands here and refuses instead of splitting the block.
        <InlineComboboxItem value="loading" onSelect={() => false}>
          Loading emoji…
        </InlineComboboxItem>
      ) : (
        <InlineComboboxEmpty>
          {catalog === 'failed' ? 'Emoji unavailable' : 'No results'}
        </InlineComboboxEmpty>
      )}

      <InlineComboboxGroup>
        {emojis.map((emoji) => (
          <InlineComboboxItem
            key={emoji.emoji}
            value={emoji.label}
            onSelect={(tx) => {
              tx.text.insert(emoji.emoji);
            }}
          >
            {emoji.emoji} {emoji.label}
          </InlineComboboxItem>
        ))}
      </InlineComboboxGroup>
    </InlineComboboxContent>
  );
}

export const EmojiPlugin = definePlugin('emoji', {
  editOnly: true,
  initialState: (): ComboboxState => ({
    maxQueryLength: 75,
    queryPattern: /^[\p{L}\p{N}_+\-:]$/u,
    trigger: ':',
    triggerPreviousCharPattern: /^\s?$/,
    triggerQuery: (editor) => {
      const codeBlock = editor.plugin(BaseCodeBlockPlugin);

      return (
        !codeBlock.installed ||
        !editor.read.nodes.some({ type: codeBlock.schema.type })
      );
    },
  }),
});

export const EmojiKit = [
  EmojiPlugin.configure({ slots: { afterEditable: EmojiCombobox } }),
];
